4	@theme {
5	  /* Futuristic Cyber Color Palette */
6	  --color-background: #050508;
7	  --color-surface: #0a0a10;
8	  --color-surface-hover: #12121a;
9	  --color-primary: #00f0ff;
10	  --color-primary-hover: #00c8d4;
11	  --color-secondary: #bf00ff;
12	  --color-accent: #ff0080;
13	  --color-neon-green: #00ff88;
14	  --color-neon-yellow: #f0ff00;
15	  --color-warning: #ff6b00;
16	  --color-text-main: #e8e8ff;
17	  --color-text-muted: #5a5a7a;
18	  --color-grid: rgba(0, 240, 255, 0.02);
19	  --color-border-glow: rgba(0, 240, 255, 0.5);
20	
21	  /* Core Animations */
22	  --animate-fade-in: fade-in 0.8s ease-out forwards;
23	  --animate-slide-up: slide-up 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
24	  --animate-slide-down: slide-down 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
25	  --animate-scale-in: scale-in 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
26	  --animate-float: float 6s ease-in-out infinite;
27	  --animate-float-slow: float-slow 12s ease-in-out infinite;
28	  --animate-float-reverse: float-reverse 10s ease-in-out infinite;
29	  --animate-pulse-glow: pulse-glow 3s ease-in-out infinite;
30	  --animate-scan-line: scan-line 6s linear infinite;
31	  --animate-scan-horizontal: scan-horizontal 8s linear infinite;
32	  --animate-glitch: glitch 0.4s ease-in-out;
33	  --animate-glitch-loop: glitch-loop 3s infinite;
34	  --animate-border-flow: border-flow 4s linear infinite;
35	  --animate-flicker: flicker 4s linear infinite;
36	  --animate-data-stream: data-stream 20s linear infinite;
37	  --animate-rotate: rotate 20s linear infinite;
38	  --animate-particle: particle 20s linear infinite;
39	  --animate-chromatic: chromatic 0.3s ease-out;
40	  --animate-text-shimmer: text-shimmer 3s linear infinite;
