738	   CRT SCREEN EFFECT
739	   ============================================ */
740	.crt-effect {
741	  position: relative;
742	}
743	
744	.crt-effect::before {
745	  content: "";
746	  position: absolute;
747	  inset: 0;
748	  background: repeating-linear-gradient(
749	    0deg,
750	    rgba(0, 0, 0, 0.15),
751	    rgba(0, 0, 0, 0.15) 1px,
752	    transparent 1px,
753	    transparent 2px
754	  );
