37	
38	function ErrorBoundary({ error }: { error: unknown }) {
39	  // Log error to console in development
40	  if (process.env.NODE_ENV === "development") {
41	    console.error("ErrorBoundary caught an error:", error);
42	  }
43	
44	  const getErrorMessage = (error: unknown): string => {
45	    if (error instanceof Error) {
46	      return error.message;
47	    }
48	    if (typeof error === "string") {
49	      return error;
50	    }
51	    return "An unexpected error occurred. Don't worry, it happens!";
52	  };
53	
54	  const getErrorStack = (error: unknown): string | null => {
55	    if (error instanceof Error && process.env.NODE_ENV === "development") {
56	      return error.stack ?? null;
57	    }
58	    return null;
59	  };
60	
61	  const errorMessage = getErrorMessage(error);
62	  const errorStack = getErrorStack(error);
63	
64	  return (
65	    <html lang="en" className="h-full bg-background text-text-main">
66	      <head>
67	        <title>Oh no!</title>
68	        <HeadContent />
69	      </head>
70	      <body className="flex justify-center items-center min-h-screen">
71	        <div className="relative p-8 max-w-xl mx-4 text-center">
72	          <h1 className="text-3xl font-bold text-primary mb-6 max-w-full">
73	            Oops! Something went wrong...
74	          </h1>
75	          <p className="text-lg text-text-muted mb-6">{errorMessage}</p>
76	
77	          {errorStack && (
78	            <details className="mb-6">
79	              <summary className="cursor-pointer text-text-main mb-2">Show Error Details</summary>
80	              <pre className="bg-surface p-4 rounded-lg text-sm text-text-muted overflow-x-auto max-h-32 border border-surface-hover animate-fade-in text-left">
81	                {errorStack}
82	              </pre>
83	            </details>
84	          )}
85	
86	          <a
87	            href="/"
88	            className="inline-block bg-primary text-white text-sm font-semibold py-3 px-8 rounded-full shadow-lg transition-transform transform hover:scale-105 hover:shadow-xl animate-fade-in"
89	          >
90	            Take me Home
91	          </a>
92	        </div>
93	        <Scripts />
94	      </body>
95	    </html>
96	  );
97	}
