@import "tailwindcss";
@plugin "@tailwindcss/typography";

@theme {
  /* Refined dark palette — one accent, calm neutrals */
  --color-background: #0b0d10;
  --color-surface: #12151a;
  --color-surface-hover: #191d24;
  --color-border-subtle: #232830;
  --color-primary: #22d3ee;
  --color-primary-hover: #67e8f9;
  --color-secondary: #94a3b8;
  --color-neon-green: #34d399;
  --color-neon-yellow: #fbbf24;
  --color-text-main: #e7eaf0;
  --color-text-muted: #9aa3b2;

  --animate-fade-in: fade-in 0.4s ease-out forwards;
  --animate-scale-in: scale-in 0.2s ease-out forwards;

  @keyframes fade-in {
    from {
      opacity: 0;
      transform: translateY(8px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes scale-in {
    from {
      transform: scale(0.98);
      opacity: 0;
    }
    to {
      transform: scale(1);
      opacity: 1;
    }
  }
}

/* ============================================
   BASE STYLES
   ============================================ */
html {
  scroll-behavior: smooth;
}

body {
  background-color: var(--color-background);
  color: var(--color-text-main);
  font-family:
    "Inter",
    system-ui,
    -apple-system,
    sans-serif;
  overflow-x: hidden;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
}

/* Monospace for small metadata labels (dates, tags, kbd hints) */
.terminal-text {
  font-family: "JetBrains Mono", "Fira Code", "SF Mono", "Consolas", monospace;
  letter-spacing: 0.02em;
}

/* ============================================
   CARD
   ============================================ */
.card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border-subtle);
  border-radius: 0.75rem;
  transition:
    border-color 0.2s ease,
    background-color 0.2s ease;
}

.card:hover {
  border-color: color-mix(in srgb, var(--color-primary) 35%, var(--color-border-subtle));
  background-color: var(--color-surface-hover);
}

/* ============================================
   STATUS INDICATOR (command palette)
   ============================================ */
.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-neon-green);
}

/* ============================================
   FOCUS VISIBILITY
   ============================================ */
:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ============================================
   CUSTOM SCROLLBAR
   ============================================ */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--color-background);
}

::-webkit-scrollbar-thumb {
  background: var(--color-border-subtle);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--color-text-muted);
}

/* ============================================
   SELECTION COLOR
   ============================================ */
::selection {
  background: color-mix(in srgb, var(--color-primary) 30%, transparent);
  color: var(--color-text-main);
}

/* ============================================
   REDUCED MOTION
   ============================================ */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

import { Link } from "@tanstack/react-router";
import { useState, useEffect } from "react";

const navLinks = [
  { to: "/blog", label: "Blog" },
  { to: "/reading-list", label: "Reading" },
  { to: "/tool", label: "Tools" },
];

export const Header = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  useEffect(() => {
    if (isMenuOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [isMenuOpen]);

  return (
    <header className="sticky top-0 z-[110] bg-background/85 backdrop-blur-lg border-b border-border-subtle">
      <div className="max-w-5xl mx-auto px-6 h-16 flex items-center justify-between">
        {/* Logo */}
        <Link
          to="/"
          className="font-semibold text-text-main hover:text-primary transition-colors"
        >
          Xiaofeng Xie
        </Link>

        {/* Desktop Navigation */}
        <nav className="hidden md:flex items-center gap-1">
          {navLinks.map((link) => (
            <Link
              key={link.to}
              to={link.to}
              className="px-3 py-2 text-sm text-text-muted hover:text-text-main rounded-md hover:bg-surface transition-colors"
              activeProps={{ className: "text-text-main bg-surface" }}
            >
              {link.label}
            </Link>
          ))}

          {/* Command palette trigger */}
          <button
            type="button"
            onClick={() => window.dispatchEvent(new CustomEvent("toggle-command-agent"))}
            className="ml-3 flex items-center gap-2 px-3 py-1.5 text-sm text-text-muted border border-border-subtle rounded-md hover:border-text-muted/50 hover:text-text-main transition-colors"
          >
            Search
            <kbd className="terminal-text text-[10px] text-text-muted px-1.5 py-0.5 border border-border-subtle rounded bg-surface">
              ⌘K
            </kbd>
          </button>
        </nav>

        {/* Mobile Menu Button */}
        <button
          className="md:hidden w-10 h-10 flex items-center justify-center rounded-md border border-border-subtle hover:bg-surface transition-colors"
          onClick={() => setIsMenuOpen(!isMenuOpen)}
          aria-label="Toggle menu"
          aria-expanded={isMenuOpen}
        >
          <div className="flex flex-col gap-1.5 items-center justify-center">
            <span
              className={`w-4 h-0.5 bg-text-main transition-all duration-300 ${isMenuOpen ? "rotate-45 translate-y-2" : ""}`}
            />
            <span
              className={`w-4 h-0.5 bg-text-main transition-all duration-300 ${isMenuOpen ? "opacity-0" : ""}`}
            />
            <span
              className={`w-4 h-0.5 bg-text-main transition-all duration-300 ${isMenuOpen ? "-rotate-45 -translate-y-2" : ""}`}
            />
          </div>
        </button>
      </div>

      {/* Mobile Navigation */}
      <div
        className={`md:hidden fixed inset-0 top-16 z-[120] transition-opacity duration-200 ${isMenuOpen ? "opacity-100 visible" : "opacity-0 invisible pointer-events-none"}`}
        aria-hidden={!isMenuOpen}
      >
        {/* Backdrop */}
        <button
          type="button"
          className="absolute inset-0 bg-black/60 backdrop-blur-sm"
          onClick={() => setIsMenuOpen(false)}
          aria-label="Close menu"
        />
        {/* Menu panel */}
        <div className="absolute top-0 left-0 right-0 bg-background border-b border-border-subtle shadow-xl">
          <nav className="max-w-5xl mx-auto px-6 py-4 space-y-1">
            <Link
              to="/"
              className="block px-4 py-3 rounded-md text-text-muted hover:text-text-main hover:bg-surface transition-colors"
              activeProps={{ className: "text-text-main bg-surface" }}
              activeOptions={{ exact: true }}
              onClick={() => setIsMenuOpen(false)}
            >
              Home
            </Link>
            {navLinks.map((link) => (
              <Link
                key={link.to}
                to={link.to}
                className="block px-4 py-3 rounded-md text-text-muted hover:text-text-main hover:bg-surface transition-colors"
                activeProps={{ className: "text-text-main bg-surface" }}
                onClick={() => setIsMenuOpen(false)}
              >
                {link.label}
              </Link>
            ))}
          </nav>
        </div>
      </div>
    </header>
  );
};

