import { createFileRoute, Link } from "@tanstack/react-router";
import { fetchAllBlogPosts } from "~/server/blog.functions";

export const Route = createFileRoute("/blog/")({
  loader: async () => ({ posts: await fetchAllBlogPosts() }),
  head: () => ({
    meta: [
